-- Reconcile 25 exact retailer title identities from the remaining Weruva-family
-- census queue to 23 already verified manufacturer-current can formulas.
--
-- Retailer sitemap titles remain identity leads only: this migration does not
-- treat the retailer pages as ingredient or image verification and does not
-- modify product_data, ingredient text, package images, or formula versions.
-- Every alias is hard-gated by shelf brand, species, life stage, food form,
-- explicit can presentation, exact visible official product name, GTIN,
-- current official source/image, and the stored ingredient-version hash.

ALTER TABLE public.catalog_field_evidence
  DROP CONSTRAINT catalog_field_evidence_source_authority_check;

ALTER TABLE public.catalog_field_evidence
  ADD CONSTRAINT catalog_field_evidence_source_authority_check
  CHECK (
    source_authority = ANY (
      ARRAY[
        'gdsn'::TEXT,
        'official'::TEXT,
        'manufacturer'::TEXT,
        'retailer_verified'::TEXT,
        'retailer_identity'::TEXT
      ]
    )
  );

ALTER TABLE public.catalog_verified_product_search_aliases
  DROP CONSTRAINT catalog_verified_product_search_aliases_authority_check;

ALTER TABLE public.catalog_verified_product_search_aliases
  ADD CONSTRAINT catalog_verified_product_search_aliases_authority_check
  CHECK (
    source_authority = ANY (
      ARRAY[
        'manufacturer'::TEXT,
        'official'::TEXT,
        'gdsn'::TEXT,
        'retailer_verified'::TEXT,
        'label_ocr_verified'::TEXT,
        'retailer_identity'::TEXT
      ]
    )
  );

CREATE TEMP TABLE weruva_retailer_alias_payload
ON COMMIT DROP
AS
SELECT
  raw.*,
  public.normalize_verified_product_search_query(raw.retailer_title)
    AS normalized_alias
FROM jsonb_to_recordset(
  convert_from(
    decode('', 'base64'),
    'utf8'
  )::JSONB
) AS raw(
  alias_formula_key TEXT,
  retailer_title TEXT,
  retailer_source_url TEXT,
  retailer_product_id TEXT,
  retailer_front_image_url TEXT,
  retailer_observed_at TIMESTAMPTZ,
  retailer_source_slug TEXT,
  expected_shelf_brand TEXT,
  observed_package_kinds JSONB,
  target_cache_key TEXT,
  target_brand TEXT,
  target_product_name TEXT,
  target_pet_type TEXT,
  target_life_stage TEXT,
  target_food_form TEXT,
  target_source_url TEXT,
  target_image_url TEXT,
  target_package_size TEXT,
  target_gtin TEXT,
  target_ingredient_hash TEXT,
  target_ingredient_count INTEGER,
  formula_id_hint BIGINT
);

DO $guard$
DECLARE
  v_key TEXT;
BEGIN
  IF (SELECT count(*) FROM weruva_retailer_alias_payload) <> 25 THEN
    RAISE EXCEPTION 'Weruva retailer identity payload must contain 25 rows';
  END IF;

  IF (
    SELECT count(DISTINCT alias_formula_key)
    FROM weruva_retailer_alias_payload
  ) <> 25 THEN
    RAISE EXCEPTION 'Weruva retailer identity formula keys are not unique';
  END IF;

  IF (
    SELECT count(DISTINCT normalized_alias)
    FROM weruva_retailer_alias_payload
  ) <> 25 THEN
    RAISE EXCEPTION 'Weruva retailer identity search aliases are not unique';
  END IF;

  SELECT alias_formula_key
  INTO v_key
  FROM weruva_retailer_alias_payload
  WHERE NULLIF(btrim(alias_formula_key), '') IS NULL
     OR NULLIF(btrim(retailer_title), '') IS NULL
     OR NULLIF(btrim(retailer_source_url), '') IS NULL
     OR NULLIF(btrim(retailer_product_id), '') IS NULL
     OR NULLIF(btrim(target_cache_key), '') IS NULL
     OR NULLIF(btrim(target_source_url), '') IS NULL
     OR NULLIF(btrim(target_image_url), '') IS NULL
     OR NULLIF(btrim(target_package_size), '') IS NULL
     OR NULLIF(btrim(target_gtin), '') IS NULL
     OR target_ingredient_hash !~ '^[a-f0-9]{64}$'
     OR target_ingredient_count < 5
     OR normalized_alias IS NULL
     OR length(normalized_alias) < 2
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Weruva retailer identity payload is incomplete: %', v_key;
  END IF;

  SELECT alias_formula_key
  INTO v_key
  FROM weruva_retailer_alias_payload
  WHERE jsonb_typeof(observed_package_kinds) <> 'array'
     OR observed_package_kinds <> '["can"]'::JSONB
     OR lower(btrim(expected_shelf_brand)) <> lower(btrim(target_brand))
     OR target_pet_type NOT IN ('dog', 'cat')
     OR target_food_form <> 'wet'
     OR lower(retailer_title) LIKE '%meals %n more%'
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Weruva retailer identity boundary is unsafe: %', v_key;
  END IF;

  IF (
    SELECT count(*)
    FROM weruva_retailer_alias_payload
    WHERE retailer_source_slug = 'chewy-public-sitemap'
  ) <> 23 OR (
    SELECT count(*)
    FROM weruva_retailer_alias_payload
    WHERE retailer_source_slug = 'walmart-public-sitemap'
  ) <> 2 THEN
    RAISE EXCEPTION 'Weruva retailer identity source partition changed';
  END IF;

  SELECT p.alias_formula_key
  INTO v_key
  FROM weruva_retailer_alias_payload p
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.product_data product
    WHERE product.cache_key = p.target_cache_key
      AND lower(btrim(product.brand)) = lower(btrim(p.target_brand))
      AND lower(btrim(product.product_name)) =
          lower(btrim(p.target_product_name))
      AND product.pet_type = p.target_pet_type
      AND coalesce(
            nullif(lower(btrim(product.life_stage)), 'unknown'),
            ''
          ) = coalesce(
            nullif(lower(btrim(p.target_life_stage)), 'unknown'),
            ''
          )
      AND product.food_form = p.target_food_form
      AND product.source_url = p.target_source_url
      AND product.image_url = p.target_image_url
      AND coalesce(product.package_size, '') =
          coalesce(p.target_package_size, '')
      AND coalesce(product.gtin, '') = p.target_gtin
      AND product.ingredient_count = p.target_ingredient_count
      AND coalesce(
            nullif(
              product.formula_version_provenance
                ->> 'ingredient_text_hash',
              ''
            ),
            encode(
              digest(
                public.catalog_normalize_ingredient_evidence(
                  product.ingredient_text
                ),
                'sha256'
              ),
              'hex'
            )
          ) = p.target_ingredient_hash
      AND product.formula_evidence_tier = 'manufacturer_current_exact'
      AND product.source_quality = 'manufacturer'
      AND product.ingredient_verification_status = 'manufacturer'
      AND product.image_verification_status = 'manufacturer'
      AND product.is_complete_food
      AND product.catalog_exclusion_reason IS NULL
      AND product.expires_at > now()
      AND product.verified_at IS NOT NULL
  )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'Weruva retailer identity serving precondition changed: %',
      v_key;
  END IF;
END
$guard$;

CREATE TEMP TABLE weruva_retailer_alias_resolved
ON COMMIT DROP
AS
SELECT
  payload.*,
  formula.id AS formula_id,
  formula.formula_key AS canonical_formula_key,
  formula.identity_hash AS canonical_identity_hash,
  observation.id AS observation_id
FROM weruva_retailer_alias_payload payload
JOIN public.catalog_formulas formula
  ON formula.promoted_cache_key = payload.target_cache_key
 AND formula.active
 AND formula.verification_status = 'verified'
 AND formula.formula_evidence_tier = 'manufacturer_current_exact'
 AND formula.is_complete_food
 AND lower(btrim(formula.brand)) = lower(btrim(payload.target_brand))
 AND lower(btrim(formula.product_name)) =
     lower(btrim(payload.target_product_name))
 AND formula.pet_type = payload.target_pet_type
 AND coalesce(
       nullif(lower(btrim(formula.life_stage)), 'unknown'),
       ''
     ) = coalesce(
       nullif(lower(btrim(payload.target_life_stage)), 'unknown'),
       ''
     )
 AND formula.food_form = payload.target_food_form
 AND coalesce(
       nullif(formula.formula_version_provenance ->> 'ingredient_text_hash', ''),
       encode(
         digest(
           public.catalog_normalize_ingredient_evidence(
             formula.ingredient_text
           ),
           'sha256'
         ),
         'hex'
       )
     ) = payload.target_ingredient_hash
JOIN LATERAL (
  SELECT exact_observation.id
  FROM public.catalog_observations exact_observation
  WHERE exact_observation.source_slug = payload.retailer_source_slug
    AND exact_observation.source_external_id = payload.retailer_product_id
    AND lower(regexp_replace(exact_observation.source_url, '/+$', '')) =
        lower(regexp_replace(payload.retailer_source_url, '/+$', ''))
  ORDER BY
    exact_observation.observed_at DESC,
    exact_observation.created_at DESC,
    exact_observation.id DESC
  LIMIT 1
) observation ON TRUE;

DO $resolution_guard$
DECLARE
  v_key TEXT;
BEGIN
  SELECT payload.alias_formula_key
  INTO v_key
  FROM weruva_retailer_alias_payload payload
  LEFT JOIN (
    SELECT alias_formula_key, count(*) AS candidate_count
    FROM weruva_retailer_alias_resolved
    GROUP BY alias_formula_key
  ) resolved USING (alias_formula_key)
  WHERE coalesce(resolved.candidate_count, 0) <> 1
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'Weruva retailer identity formula/observation did not resolve uniquely: %',
      v_key;
  END IF;

  SELECT alias_formula_key
  INTO v_key
  FROM weruva_retailer_alias_resolved
  WHERE formula_id_hint IS NOT NULL
    AND formula_id_hint <> formula_id
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'Weruva retailer identity formula hint disagrees with stable resolution: %',
      v_key;
  END IF;

  SELECT resolved.alias_formula_key
  INTO v_key
  FROM weruva_retailer_alias_resolved resolved
  JOIN public.catalog_formula_aliases existing
    USING (alias_formula_key)
  WHERE existing.formula_id <> resolved.formula_id
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'Weruva retailer identity formula alias collision: %',
      v_key;
  END IF;

  SELECT resolved.alias_formula_key
  INTO v_key
  FROM weruva_retailer_alias_resolved resolved
  JOIN public.catalog_verified_product_search_aliases existing
    ON existing.active
   AND existing.normalized_alias = resolved.normalized_alias
  WHERE existing.cache_key <> resolved.target_cache_key
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'Weruva retailer identity search alias collision: %',
      v_key;
  END IF;
END
$resolution_guard$;

INSERT INTO public.catalog_formula_aliases (
  alias_formula_key,
  formula_id,
  identity_hash,
  match_reason,
  source_url,
  metadata,
  updated_at
)
SELECT
  resolved.alias_formula_key,
  resolved.formula_id,
  resolved.canonical_identity_hash,
  'manual_review',
  resolved.retailer_source_url,
  jsonb_build_object(
    'source', 'weruva_retailer_identity_reconciliation_20260804',
    'retailer_identity_only', TRUE,
    'retailer_ingredient_verification', FALSE,
    'retailer_image_present',
      NULLIF(btrim(resolved.retailer_front_image_url), '') IS NOT NULL,
    'retailer_source_slug', resolved.retailer_source_slug,
    'retailer_product_id', resolved.retailer_product_id,
    'retailer_title', resolved.retailer_title,
    'retailer_source_url', resolved.retailer_source_url,
    'retailer_front_image_url', resolved.retailer_front_image_url,
    'retailer_observed_at', resolved.retailer_observed_at,
    'official_source_url', resolved.target_source_url,
    'official_front_image_url', resolved.target_image_url,
    'official_cache_key', resolved.target_cache_key,
    'canonical_formula_key', resolved.canonical_formula_key,
    'ingredient_text_hash', resolved.target_ingredient_hash,
    'ingredient_count', resolved.target_ingredient_count,
    'shelf_brand_boundary', resolved.target_brand,
    'species_boundary', resolved.target_pet_type,
    'life_stage_boundary',
      coalesce(NULLIF(resolved.target_life_stage, ''), 'unknown'),
    'food_form_boundary', resolved.target_food_form,
    'package_kind_boundary', resolved.observed_package_kinds,
    'exact_visible_official_name', TRUE,
    'package_size_is_sku_only', TRUE,
    'ingredient_or_image_rewrite', FALSE,
    'reviewed_at', now()
  ),
  now()
FROM weruva_retailer_alias_resolved resolved
ON CONFLICT (alias_formula_key) DO UPDATE
SET formula_id = EXCLUDED.formula_id,
    identity_hash = EXCLUDED.identity_hash,
    match_reason = EXCLUDED.match_reason,
    source_url = EXCLUDED.source_url,
    metadata = public.catalog_formula_aliases.metadata || EXCLUDED.metadata,
    updated_at = now()
WHERE public.catalog_formula_aliases.formula_id = EXCLUDED.formula_id;

INSERT INTO public.catalog_verified_product_search_aliases (
  cache_key,
  alias_text,
  normalized_alias,
  source_url,
  source_authority,
  evidence_observed_at,
  provenance,
  active,
  updated_at
)
SELECT
  resolved.target_cache_key,
  resolved.retailer_title,
  resolved.normalized_alias,
  resolved.retailer_source_url,
  'retailer_identity',
  resolved.retailer_observed_at,
  jsonb_build_object(
    'source', 'weruva_retailer_identity_reconciliation_20260804',
    'retailer_identity_only', TRUE,
    'retailer_ingredient_verification', FALSE,
    'retailer_image_present',
      NULLIF(btrim(resolved.retailer_front_image_url), '') IS NOT NULL,
    'retailer_source_slug', resolved.retailer_source_slug,
    'retailer_product_id', resolved.retailer_product_id,
    'retailer_source_url', resolved.retailer_source_url,
    'official_source_url', resolved.target_source_url,
    'official_front_image_url', resolved.target_image_url,
    'formula_id', resolved.formula_id,
    'canonical_formula_key', resolved.canonical_formula_key,
    'ingredient_text_hash', resolved.target_ingredient_hash,
    'shelf_brand_boundary', resolved.target_brand,
    'species_boundary', resolved.target_pet_type,
    'life_stage_boundary',
      coalesce(NULLIF(resolved.target_life_stage, ''), 'unknown'),
    'food_form_boundary', resolved.target_food_form,
    'package_kind_boundary', resolved.observed_package_kinds,
    'exact_visible_official_name', TRUE,
    'ingredient_or_image_rewrite', FALSE
  ),
  TRUE,
  now()
FROM weruva_retailer_alias_resolved resolved
ON CONFLICT (normalized_alias) WHERE active DO UPDATE
SET cache_key = EXCLUDED.cache_key,
    alias_text = EXCLUDED.alias_text,
    source_url = EXCLUDED.source_url,
    source_authority = EXCLUDED.source_authority,
    evidence_observed_at = EXCLUDED.evidence_observed_at,
    provenance =
      public.catalog_verified_product_search_aliases.provenance
      || EXCLUDED.provenance,
    updated_at = now()
WHERE public.catalog_verified_product_search_aliases.cache_key =
      EXCLUDED.cache_key;

INSERT INTO public.catalog_field_evidence (
  formula_id,
  observation_id,
  field_name,
  field_value,
  source_url,
  source_authority,
  accepted,
  observed_at,
  content_hash
)
SELECT
  resolved.formula_id,
  resolved.observation_id,
  'retailer_exact_identity_alias',
  jsonb_build_object(
    'source', 'weruva_retailer_identity_reconciliation_20260804',
    'retailer_identity_only', TRUE,
    'retailer_ingredient_verification', FALSE,
    'retailer_title', resolved.retailer_title,
    'retailer_product_id', resolved.retailer_product_id,
    'retailer_source_slug', resolved.retailer_source_slug,
    'retailer_front_image_url', resolved.retailer_front_image_url,
    'official_source_url', resolved.target_source_url,
    'official_front_image_url', resolved.target_image_url,
    'official_cache_key', resolved.target_cache_key,
    'canonical_formula_key', resolved.canonical_formula_key,
    'ingredient_text_hash', resolved.target_ingredient_hash,
    'shelf_brand_boundary', resolved.target_brand,
    'species_boundary', resolved.target_pet_type,
    'life_stage_boundary',
      coalesce(NULLIF(resolved.target_life_stage, ''), 'unknown'),
    'food_form_boundary', resolved.target_food_form,
    'package_kind_boundary', resolved.observed_package_kinds,
    'exact_visible_official_name', TRUE,
    'package_size_is_sku_only', TRUE,
    'ingredient_or_image_rewrite', FALSE
  ),
  resolved.retailer_source_url,
  'retailer_identity',
  TRUE,
  resolved.retailer_observed_at,
  encode(
    digest(
      resolved.formula_id::TEXT
      || '|weruva_retailer_identity|'
      || resolved.alias_formula_key
      || '|'
      || resolved.retailer_source_url
      || '|'
      || resolved.target_ingredient_hash,
      'sha256'
    ),
    'hex'
  )
FROM weruva_retailer_alias_resolved resolved
ON CONFLICT (
  formula_id,
  field_name,
  source_url,
  content_hash
) DO UPDATE
SET observation_id = EXCLUDED.observation_id,
    field_value = EXCLUDED.field_value,
    source_authority = EXCLUDED.source_authority,
    accepted = TRUE,
    observed_at = EXCLUDED.observed_at;

DO $postconditions$
DECLARE
  v_resolved RECORD;
  v_top_cache_key TEXT;
  v_key TEXT;
BEGIN
  IF (
    SELECT count(*)
    FROM weruva_retailer_alias_resolved resolved
    JOIN public.catalog_formula_aliases alias
      USING (alias_formula_key)
    WHERE alias.formula_id = resolved.formula_id
      AND alias.match_reason = 'manual_review'
      AND alias.metadata ->> 'source' =
          'weruva_retailer_identity_reconciliation_20260804'
      AND (alias.metadata ->> 'retailer_identity_only')::BOOLEAN
      AND NOT (
        alias.metadata ->> 'retailer_ingredient_verification'
      )::BOOLEAN
  ) <> 25 THEN
    RAISE EXCEPTION 'Weruva retailer identity formula alias postcondition failed';
  END IF;

  IF (
    SELECT count(*)
    FROM weruva_retailer_alias_resolved resolved
    JOIN public.catalog_verified_product_search_aliases alias
      ON alias.active
     AND alias.normalized_alias = resolved.normalized_alias
    WHERE alias.cache_key = resolved.target_cache_key
      AND alias.source_authority = 'retailer_identity'
      AND alias.provenance ->> 'source' =
          'weruva_retailer_identity_reconciliation_20260804'
      AND (alias.provenance ->> 'retailer_identity_only')::BOOLEAN
      AND NOT (
        alias.provenance ->> 'retailer_ingredient_verification'
      )::BOOLEAN
  ) <> 25 THEN
    RAISE EXCEPTION 'Weruva retailer identity search alias postcondition failed';
  END IF;

  IF (
    SELECT count(*)
    FROM weruva_retailer_alias_resolved resolved
    JOIN public.catalog_field_evidence evidence
      ON evidence.formula_id = resolved.formula_id
     AND evidence.observation_id = resolved.observation_id
     AND evidence.field_name = 'retailer_exact_identity_alias'
     AND evidence.source_url = resolved.retailer_source_url
    WHERE evidence.accepted
      AND evidence.source_authority = 'retailer_identity'
      AND evidence.field_value ->> 'source' =
          'weruva_retailer_identity_reconciliation_20260804'
      AND (evidence.field_value ->> 'retailer_identity_only')::BOOLEAN
      AND NOT (
        evidence.field_value ->> 'retailer_ingredient_verification'
      )::BOOLEAN
  ) <> 25 THEN
    RAISE EXCEPTION 'Weruva retailer identity evidence postcondition failed';
  END IF;

  FOR v_resolved IN
    SELECT *
    FROM weruva_retailer_alias_resolved
    ORDER BY alias_formula_key
  LOOP
    SELECT result.cache_key
    INTO v_top_cache_key
    FROM public.search_verified_products(v_resolved.retailer_title, 8) result
    ORDER BY result.rank DESC
    LIMIT 1;

    IF v_top_cache_key IS DISTINCT FROM v_resolved.target_cache_key THEN
      RAISE EXCEPTION
        'Weruva retailer exact-title search regression for %: expected %, got %',
        v_resolved.retailer_product_id,
        v_resolved.target_cache_key,
        v_top_cache_key;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.search_verified_products(v_resolved.retailer_title, 8) result
      WHERE lower(btrim(result.brand)) <> lower(btrim(v_resolved.target_brand))
         OR result.pet_type <> v_resolved.target_pet_type
         OR result.food_form <> v_resolved.target_food_form
    ) THEN
      RAISE EXCEPTION
        'Weruva retailer exact-title search crossed an identity boundary: %',
        v_resolved.retailer_product_id;
    END IF;
  END LOOP;

  SELECT resolved.alias_formula_key
  INTO v_key
  FROM weruva_retailer_alias_resolved resolved
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.product_data product
    WHERE product.cache_key = resolved.target_cache_key
      AND product.source_url = resolved.target_source_url
      AND product.image_url = resolved.target_image_url
      AND product.gtin = resolved.target_gtin
      AND product.ingredient_count = resolved.target_ingredient_count
      AND coalesce(
            nullif(
              product.formula_version_provenance
                ->> 'ingredient_text_hash',
              ''
            ),
            encode(
              digest(
                public.catalog_normalize_ingredient_evidence(
                  product.ingredient_text
                ),
                'sha256'
              ),
              'hex'
            )
          ) = resolved.target_ingredient_hash
      AND product.formula_evidence_tier = 'manufacturer_current_exact'
      AND product.ingredient_verification_status = 'manufacturer'
      AND product.image_verification_status = 'manufacturer'
  )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'Weruva retailer identity changed serving evidence: %',
      v_key;
  END IF;
END
$postconditions$;
